        ...prev,
        items: newItems,
        lowStockItems: newItems.filter(i => i.quantity <= i.min_threshold)
      };
    });
    try {
      const res = await authFetch(`/api/pantry/${id}`, { method: 'DELETE' });
      if (!res.ok) throw new Error('Failed to delete item');
      success('Item removed from pantry.');
      notifyDataChanged();
      fetchPantryData();
    } catch (err) {
      error(err.message);
      fetchPantryData();
    }
  };"

